{"command":["bash","-lc","python3 - <<'PY'
import json, collections, math, itertools, statistics
rows=[]
for line in open('/app/lab_log.jsonl'):
    o=json.loads(line)
    if o['op']=='dev_sample': rows.append(o)
print('calls', len(rows), 'credits', sum(r['result']['cost'] for r in rows))
qs=[]
for r in rows:
    for q in r['result']['questions']:
        qs.append(q)
print('questions', len(qs), collections.Counter(q['topic'] for q in qs))
for topic in sorted(set(q['topic'] for q in qs)):
    tq=[q for q in qs if q['topic']==topic]
    print('\nTOPIC',topic,'nq',len(tq))
    for v in range(5):
        ss=[s for q in tq for s in q['samples'] if s['variant']==v]
        print(' v',v,'sample acc',sum(s['correct'] for s in ss)/len(ss),'mean score c/w',
              statistics.mean([s['score'] for s in ss if s['correct']]) if any(s['correct'] for s in ss) else None,
              statistics.mean([s['score'] for s in ss if not s['correct']]) if any(not s['correct'] for s in ss) else None)
    # using all 10 samples choose rules
    def best_score(q): return max(q['samples'], key=lambda s:s['score'])['correct']
    def majority(q):
        c=collections.Counter(s['answer'] for s in q['samples'])
        mx=max(c.values()); cand=[a for a,n in c.items() if n==mx]
        # tie by max score
        best=max(cand, key=lambda a:max(s['score'] for s in q['samples'] if s['answer']==a))
        return best==q['correct_answer']
    def sumexp(q,t=1):
        d=collections.defaultdict(float)
        for s in q['samples']: d[s['answer']]+=math.exp(t*s['score'])
        return max(d,key=d.get)==q['correct_answer']
    def sumscore(q,alpha=1,beta=0):
        d=collections.defaultdict(float)
        for s in q['samples']: d[s['answer']]+=alpha*s['score']+beta
        return max(d,key=d.get)==q['correct_answer']
    print(' all10 best_score',sum(best_score(q) for q in tq)/len(tq),'majority',sum(majority(q) for q in tq)/len(tq),'sumexp1',sum(sumexp(q,1) for q in tq)/len(tq),'sumscore+1',sum(sumscore(q,1,1) for q in tq)/len(tq))

# global candidate scoring grid on all 10
for name, func in [('best_score',lambda q:max(q['samples'], key=lambda s:s['score'])['answer']),('majority',None)]: pass

def choose(q, params):
    topic=q['topic']; arr=q['samples']; D={}
    # params: kind, w_count, w_score, score_cap, exp_temp, variant_weights
    kind=params.get('kind','lin')
    for s in arr:
        a=s['answer']; st=D.setdefault(a, {'n':0,'sum':0,'max':-999,'vars':set()})
        st['n']+=1; st['sum']+=s['score']; st['max']=max(st['max'],s['score']); st['vars'].add(s['variant'])
    best=None; bv=-1e99
    for a,st in D.items():
        n=st['n']; mx=st['max']; sm=st['sum']; nv=len(st['vars'])
        if kind=='lin':
            val=params.get('b',0)*n + params.get('s',1)*mx + params.get('sum',0)*sm + params.get('v',0)*nv
        elif kind=='avg':
