{"command":["bash","-lc","python3 - <<'PY'
import json, collections, math, statistics, random
qs=[]
for line in open('/app/lab_log.jsonl'):
    o=json.loads(line)
    if o['op']=='dev_sample':
        for q in o['result']['questions']:
            qs.append(q)
print('nq',len(qs),collections.Counter(q['topic'] for q in qs),'credits left? see status')
# tag sample call size
big=[q for q in qs if len(q['samples'])==40]
small=[q for q in qs if len(q['samples'])==10]
print('big',len(big),'small',len(small))
for topic in sorted(set(q['topic'] for q in qs)):
  tq=[q for q in qs if q['topic']==topic]
  print('\n',topic, 'n',len(tq), 'big',sum(len(q['samples'])==40 for q in tq))
  for thresh in [-1,-0.5,0,0.3,0.6,0.9,1.2,1.5,1.8,2.1]:
    ss=[s for q in tq for s in q['samples']]
    ge=[s for s in ss if s['score']>=thresh]
    if ge: print(' score>=',thresh,'frac',len(ge)/len(ss),'prec',sum(s['correct'] for s in ge)/len(ge))
  # per answer aggregate all samples choose grid simple

def choose(q, mode, **p):
    vals={}
    stats={}
    for s in q['samples']:
        a=s['answer']
        st=stats.setdefault(a, {'n':0,'sum':0,'max':-9,'vars':set(),'pos':0,'med':0,'hi':0,'lo':0,'samples':[]})
        st['n']+=1; st['sum']+=s['score']; st['max']=max(st['max'],s['score']); st['vars'].add(s['variant']); st['samples'].append(s)
        if s['score']>=0: st['pos']+=1
        if p.get('lo',-999)<=s['score']<=p.get('hi',999): st['med']+=1
        if s['score']>p.get('trap',999): st['hi']+=1
    best=None; bv=-1e99
    for a,st in stats.items():
        n=st['n']; nv=len(st['vars']); sm=st['sum']; mx=st['max']; avg=sm/n
        if mode=='support':
            val=p.get('n',1)*n+p.get('v',0)*nv+p.get('sum',0)*sm+p.get('max',0)*mx+p.get('med',0)*st['med']-p.get('hi_pen',0)*st['hi']
        elif mode=='cap_sum':
            val=0
            for s in st['samples']:
                x=s['score']; cap=p.get('cap',999); floor=p.get('floor',-999)
                if x>cap: x=cap-p.get('over',0)*(x-cap)
                if x<floor: x=floor
                val += p.get('base',0)+p.get('coef',1)*x
            val += p.get('v',0)*nv+p.get('n',0)*n
        elif mode=='window':
            val=st['med']*p.get('med',1)+nv*p.get('v',0)+n*p.get('n',0)+sm*p.get('sum',0)+mx*p.get('max',0)
        if val>bv:
            bv=val; best=a
    return best

def acc(filt, mode, **p):
    return sum(choose(q,mode,**p)==q['correct_answer'] for q in filt)/len(filt)

topics=sorted(set(q['topic'] for q in qs))
for topic in topics:
  data=[q for q in big if q['topic']==topic]
  print('\nGrid all40',topic)
  best=[]
  for lo in [-0.2,0,0.2,0.4,0.6,0.8]:
    for hi in [0.8,1.0,1.2,1.4,1.6,1.8,2.1]:
      if hi<lo: continue
      for medw in [0.5,1,2,3]:
       for v in [0,0.2,0.5,1,2]:
        for n in [0,0.1,0.2,0.5,1]:
         for su in [0,0.1,0.2,0.5]:
          p={'lo':lo,'hi':hi,'med':medw,'v':v,'n':n,'sum':su,'max':0}
          best.append((acc(data,'window',**p),p))
  best=sorted(best,reverse=True,key=lambda x:x[0])[:5]
  for a,p in best: print(a,p)

print('\nBest cap_sum per topic all40')
for topic in topics:
  data=[q for q in big if q['topic']==topic]
  best=[]
  for cap in [0.7,0.9,1.1,1.3,1.5,1.8,2.2,99]:
   for over in [0,0.5,1,2,3]:
    for base in [0,0.2,0.5,1]:
     for v in [0,0.2,0.5,1,2]:
      for n in [0,0.1,0.2,0.5,1]:
       p={'cap':cap,'over':over,'base':base,'v':v,'n':n,'coef':1}
       best.append((acc(data,'cap_sum',**p),p))
  best=sorted(best,reverse=True,key=lambda x:x[0])[:10]
  for a,p in best[:5]: print(topic,a,p)

# Simulate limited sample protocols with prefixes from big samples. Need variant order cycles.
def take(q, schedule):
    # schedule is list of variants; take next sample from that variant in stored order
    counters=collections.Counter(); out=[]
    byv={v:[s for s in q['samples'] if s['variant']==v] for v in range(5)}
    for v in schedule:
        i=counters[v]
        if i < len(byv.get(v,[])):
            out.append(byv[v][i]); counters[v]+=1
    qq={'topic':q['topic'],'correct_answer':q['correct_answer'],'samples':out}
    return qq

